with kept_keys as (select event_type from web_events intersect select event_type from web_events where session_id in (9, 10, 35, 39)), verified as (select s.* from web_events s inner join kept_keys k on s.event_type = k.event_type) select session_id, page, min(event_time) as first_event_time, sum(duration_sec) as total_duration_sec, max(event_time) as last_seen from verified group by session_id, page order by session_id desc nulls last
